    #include <iostream>
using namespace std;

bool divBy13(string &s) {

    // Convert the string to an integer
    int num = stoi(s);

    // Check if the number is divisible by 13
    return (num % 13 == 0);
}

int main() {
    string s = "2911285";

    bool isDivisible = divBy13(s);

    if (isDivisible) {
        cout << "true" << endl;
    } else {
        cout << "false" << endl;
    }

    return 0;
}


