            C++

    #include <iostream>
using namespace std;

bool divBy13(string &s){
    int len = s.size();

    // Special case: if the number is "0"
    if (len == 1 && s[0] == '0') {
        return true;
    }

    // Make the length a multiple of 3 by padding zeros at the end
    if (len % 3 == 1) {
        s += "00";  
        len += 2;
    } else if (len % 3 == 2) {
        s += "0";   
        len += 1;
    }

    // store alternating sum of 3-digit blocks and multipiler 
    int sum = 0;   
    int p = 1; 

    // Traverse from right to left in steps of 3 digits
    for (int i = len - 1; i >= 0; i--) 
    {
        // Extract 3-digit group (units, tens, hundreds)
        int group = 0;
        group += s[i--] - '0';        
        group += (s[i--] - '0') * 10;  
        group += (s[i] - '0') * 100;   

        sum = sum + group * p;

        // Alternate the sign (+, -, +, -, ...)
        p *= -1;
    }

    // Take absolute value (optional since we're checking divisibility)
    sum = abs(sum);

    return (sum % 13 == 0);
}

int main() {
    string s = "2911285"; 

    if (divBy13(s))
        cout << "true" << endl;
    else
        cout << "false" << endl;

    return 0;
}


